[FormDataFieldEventHandler(formDataFieldStr(HcmWorkerPayroll, NVPayrollWorkerReplaceEarningCode, ReplacementMethod), FormDataFieldEventType::Modified)]
public static void ReplacementMethod_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
{
    NVPayrollReplacementMethod  replacementMethod           = sender.getValue();
    FormDataSource              workerReplaceEarningCode_ds = sender.datasource();

    workerReplaceEarningCode_ds.object(fieldNum(NVPayrollWorkerReplaceEarningCode, ReplacementMethodPerc)).allowEdit(replacementMethod == NVPayrollReplacementMethod::Percentage);
    workerReplaceEarningCode_ds.object(fieldNum(NVPayrollWorkerReplaceEarningCode, Formula)).allowEdit(replacementMethod == NVPayrollReplacementMethod::Fixed);
}

[FormDataSourceEventHandler(formDataSourceStr(HcmWorkerPayroll, NVPayrollWorkerReplaceEarningCode), FormDataSourceEventType::SelectionChanged)]
public static void NVPayrollWorkerReplaceEarningCode_OnSelectionChanged(FormDataSource sender, FormDataSourceEventArgs e)
{
    FormDataSource                      workerReplaceEarningCode_ds = sender;
    NVPayrollWorkerReplaceEarningCode   workerReplaceEarningCode    = workerReplaceEarningCode_ds.cursor();
    NVPayrollReplacementMethod          replacementMethod           = workerReplaceEarningCode.ReplacementMethod;

    workerReplaceEarningCode_ds.object(fieldNum(NVPayrollWorkerReplaceEarningCode, ReplacementMethodPerc)).allowEdit(replacementMethod == NVPayrollReplacementMethod::Percentage);
    workerReplaceEarningCode_ds.object(fieldNum(NVPayrollWorkerReplaceEarningCode, Formula)).allowEdit(replacementMethod == NVPayrollReplacementMethod::Fixed);
}
